import { ArrowDown, ArrowUp, ChevronLeft, ChevronRight, ChevronsLeft, ChevronsRight } from 'lucide-react';
import { useId, useState, type ReactNode } from 'react';
import { cn } from '../../utils/cn';
import { IconButton } from '../button';
import { TransferListPane, type TransferListItem } from './TransferListPane';
import { transferListVariants } from './transfer-list.variants';

export interface TransferListLabels {
  available: string;
  selected: string;
  searchAvailable: string;
  searchSelected: string;
  searchPlaceholder: string;
  add: string;
  addAll: string;
  remove: string;
  removeAll: string;
  moveUp: string;
  moveDown: string;
  actions: string;
  emptyAvailable: string;
  emptySelected: string;
  noMatches: string;
  reorderHint: string;
  count: (checked: number, total: number) => string;
  added: (n: number) => string;
  removed: (n: number) => string;
  moved: string;
}

const defaultLabels: TransferListLabels = {
  available: 'Available',
  selected: 'Selected',
  searchAvailable: 'Search available',
  searchSelected: 'Search selected',
  searchPlaceholder: 'Filter…',
  add: 'Add checked',
  addAll: 'Add all',
  remove: 'Remove checked',
  removeAll: 'Remove all',
  moveUp: 'Move checked up',
  moveDown: 'Move checked down',
  actions: 'Transfer actions',
  emptyAvailable: 'Everything is selected.',
  emptySelected: 'Nothing selected yet.',
  noMatches: 'No matches.',
  reorderHint: 'Alt+↑/↓ reorders',
  count: (c, t) => (c ? `${c}/${t}` : String(t)),
  added: (n) => `Added ${n} ${n === 1 ? 'item' : 'items'}.`,
  removed: (n) => `Removed ${n} ${n === 1 ? 'item' : 'items'}.`,
  moved: 'Order changed.',
};

export interface TransferListProps {
  items: TransferListItem[];
  /** Selected values, in order (controlled). */
  value?: string[];
  defaultValue?: string[];
  onValueChange?: (values: string[]) => void;
  /** Show a search field above each list. */
  searchable?: boolean;
  /** Allow reordering the selected list. */
  reorderable?: boolean;
  /** Height of each list (px or CSS length). */
  height?: number | string;
  titles?: { available?: ReactNode; selected?: ReactNode };
  labels?: Partial<TransferListLabels>;
  className?: string;
}

/**
 * Two lists, available and selected: check items (click, Space, Shift+Arrow, Ctrl+A), move
 * them across with the middle buttons, Enter or a double click, and reorder the selected list
 * (Alt+Arrow or the move buttons). Each list is a multi-select listbox with search.
 */
export function TransferList({
  items,
  value,
  defaultValue = [],
  onValueChange,
  searchable = true,
  reorderable = true,
  height = 240,
  titles,
  labels: labelsProp,
  className,
}: TransferListProps) {
  const labels = { ...defaultLabels, ...labelsProp };
  const [inner, setInner] = useState<string[]>(defaultValue);
  const selectedValues = value ?? inner;
  const [checkedLeft, setCheckedLeft] = useState<Set<string>>(new Set());
  const [checkedRight, setCheckedRight] = useState<Set<string>>(new Set());
  const [announcement, setAnnouncement] = useState('');
  const id = useId();
  const s = transferListVariants();

  const byValue = new Map(items.map((it) => [it.value, it]));
  const selectedSet = new Set(selectedValues);
  const available = items.filter((it) => !selectedSet.has(it.value));
  const selected = selectedValues.map((v) => byValue.get(v)).filter((it): it is TransferListItem => !!it);

  const commit = (next: string[], message: string) => {
    setInner(next);
    onValueChange?.(next);
    setAnnouncement(message);
  };

  const add = (values: string[]) => {
    const movable = values.filter((v) => !byValue.get(v)?.disabled && !selectedSet.has(v));
    if (!movable.length) return;
    commit([...selectedValues, ...movable], labels.added(movable.length));
    setCheckedLeft(new Set([...checkedLeft].filter((v) => !movable.includes(v))));
  };

  const remove = (values: string[]) => {
    const movable = values.filter((v) => !byValue.get(v)?.disabled);
    if (!movable.length) return;
    commit(selectedValues.filter((v) => !movable.includes(v)), labels.removed(movable.length));
    setCheckedRight(new Set([...checkedRight].filter((v) => !movable.includes(v))));
  };

  const reorder = (values: string[], delta: -1 | 1) => {
    const next = [...selectedValues];
    const set = new Set(values);
    const order = delta === -1 ? next.map((_, i) => i) : next.map((_, i) => next.length - 1 - i);
    let changed = false;
    for (const i of order) {
      const j = i + delta;
      const cur = next[i];
      const other = next[j];
      if (cur === undefined || other === undefined || !set.has(cur) || set.has(other)) continue;
      next[i] = other;
      next[j] = cur;
      changed = true;
    }
    if (changed) commit(next, labels.moved);
  };

  const checkedRightValues = selectedValues.filter((v) => checkedRight.has(v));

  return (
    <div className={cn(s.root(), className)}>
      <TransferListPane
        id={`${id}-available`}
        title={titles?.available ?? labels.available}
        items={available}
        checked={checkedLeft}
        onCheckedChange={setCheckedLeft}
        onTransfer={add}
        searchable={searchable}
        searchLabel={labels.searchAvailable}
        searchPlaceholder={labels.searchPlaceholder}
        emptyText={labels.emptyAvailable}
        noMatchesText={labels.noMatches}
        countLabel={labels.count}
        height={height}
      />
      <div role="group" aria-label={labels.actions} className={s.actions()}>
        <IconButton size="sm" variant="secondary" icon={ChevronRight} label={labels.add} className="rtl:[&_svg]:-scale-x-100" disabled={!checkedLeft.size} onClick={() => add([...checkedLeft])} />
        <IconButton size="sm" variant="secondary" icon={ChevronsRight} label={labels.addAll} className="rtl:[&_svg]:-scale-x-100" disabled={!available.some((it) => !it.disabled)} onClick={() => add(available.map((it) => it.value))} />
        <IconButton size="sm" variant="secondary" icon={ChevronLeft} label={labels.remove} className="rtl:[&_svg]:-scale-x-100" disabled={!checkedRight.size} onClick={() => remove([...checkedRight])} />
        <IconButton size="sm" variant="secondary" icon={ChevronsLeft} label={labels.removeAll} className="rtl:[&_svg]:-scale-x-100" disabled={!selected.some((it) => !it.disabled)} onClick={() => remove(selected.map((it) => it.value))} />
      </div>
      <TransferListPane
        id={`${id}-selected`}
        title={titles?.selected ?? labels.selected}
        items={selected}
        checked={checkedRight}
        onCheckedChange={setCheckedRight}
        onTransfer={remove}
        onReorder={reorderable ? reorder : undefined}
        searchable={searchable}
        searchLabel={labels.searchSelected}
        searchPlaceholder={labels.searchPlaceholder}
        emptyText={labels.emptySelected}
        noMatchesText={labels.noMatches}
        countLabel={labels.count}
        height={height}
        footer={
          reorderable ? (
            <>
              <IconButton size="sm" icon={ArrowUp} label={labels.moveUp} disabled={!checkedRightValues.length} onClick={() => reorder(checkedRightValues, -1)} />
              <IconButton size="sm" icon={ArrowDown} label={labels.moveDown} disabled={!checkedRightValues.length} onClick={() => reorder(checkedRightValues, 1)} />
              <span className={s.footHint()}>{labels.reorderHint}</span>
            </>
          ) : undefined
        }
      />
      <span role="status" className="sr-only">
        {announcement}
      </span>
    </div>
  );
}

import { Check, Search } from 'lucide-react';
import { useEffect, useState, type KeyboardEvent, type ReactNode } from 'react';
import { cn } from '../../utils/cn';
import { Input } from '../input';
import { transferListVariants } from './transfer-list.variants';

export interface TransferListItem {
  value: string;
  label: string;
  description?: string;
  disabled?: boolean;
}

const s = transferListVariants();

export interface TransferListPaneProps {
  id: string;
  title: ReactNode;
  items: TransferListItem[];
  checked: ReadonlySet<string>;
  onCheckedChange: (next: Set<string>) => void;
  /** Moves the given values to the other pane. */
  onTransfer: (values: string[]) => void;
  /** Selected pane only: moves the given values by one position. */
  onReorder?: (values: string[], delta: -1 | 1) => void;
  searchable: boolean;
  searchLabel: string;
  searchPlaceholder: string;
  emptyText: ReactNode;
  noMatchesText: ReactNode;
  countLabel: (checked: number, total: number) => string;
  footer?: ReactNode;
  height: number | string;
}

/** One side of a TransferList: title, search and a multi-select listbox (aria-activedescendant). */
export function TransferListPane({
  id,
  title,
  items,
  checked,
  onCheckedChange,
  onTransfer,
  onReorder,
  searchable,
  searchLabel,
  searchPlaceholder,
  emptyText,
  noMatchesText,
  countLabel,
  footer,
  height,
}: TransferListPaneProps) {
  const [query, setQuery] = useState('');
  const [activeValue, setActiveValue] = useState<string | null>(null);
  const q = query.trim().toLowerCase();
  const visible = q ? items.filter((it) => `${it.label} ${it.description ?? ''}`.toLowerCase().includes(q)) : items;
  const activeIndex = Math.max(0, visible.findIndex((it) => it.value === activeValue));
  const active = visible[activeIndex];
  const titleId = `${id}-title`;
  const optionId = (i: number) => `${id}-opt-${i}`;

  useEffect(() => {
    document.getElementById(optionId(activeIndex))?.scrollIntoView?.({ block: 'nearest' });
  });

  const toggle = (value: string, on?: boolean) => {
    const it = items.find((x) => x.value === value);
    if (!it || it.disabled) return;
    const next = new Set(checked);
    if (on ?? !next.has(value)) next.add(value);
    else next.delete(value);
    onCheckedChange(next);
  };

  const targets = () => (checked.size ? items.filter((it) => checked.has(it.value)).map((it) => it.value) : active && !active.disabled ? [active.value] : []);

  const onKeyDown = (e: KeyboardEvent<HTMLDivElement>) => {
    const go = (i: number) => {
      const next = visible[Math.min(Math.max(i, 0), visible.length - 1)];
      if (!next) return;
      setActiveValue(next.value);
      if (e.shiftKey) toggle(next.value, true);
    };
    if (e.altKey && onReorder && (e.key === 'ArrowUp' || e.key === 'ArrowDown')) {
      e.preventDefault();
      const values = targets();
      if (values.length) onReorder(values, e.key === 'ArrowUp' ? -1 : 1);
      if (active) setActiveValue(active.value);
      return;
    }
    if (e.key === 'ArrowDown') go(activeIndex + 1);
    else if (e.key === 'ArrowUp') go(activeIndex - 1);
    else if (e.key === 'Home') go(0);
    else if (e.key === 'End') go(visible.length - 1);
    else if (e.key === ' ' && active) toggle(active.value);
    else if (e.key === 'Enter') {
      const values = targets();
      if (values.length) onTransfer(values);
    } else if ((e.ctrlKey || e.metaKey) && e.key.toLowerCase() === 'a') {
      const all = visible.filter((it) => !it.disabled).map((it) => it.value);
      const allOn = all.every((v) => checked.has(v));
      onCheckedChange(allOn ? new Set([...checked].filter((v) => !all.includes(v))) : new Set([...checked, ...all]));
    } else return;
    e.preventDefault();
  };

  return (
    <section aria-labelledby={titleId} className={s.pane()}>
      <div className={s.paneHead()}>
        <h3 id={titleId} className={s.paneTitle()}>
          {title}
        </h3>
        <span className={s.paneCount()}>{countLabel(checked.size, items.length)}</span>
      </div>
      {searchable && (
        <div className={s.search()}>
          <Input size="sm" type="search" leadingIcon={Search} aria-label={searchLabel} placeholder={searchPlaceholder} value={query} onValueChange={(v: string) => setQuery(v)} />
        </div>
      )}
      <div
        role="listbox"
        aria-multiselectable
        aria-labelledby={titleId}
        aria-activedescendant={active ? optionId(activeIndex) : undefined}
        tabIndex={0}
        className={s.listbox()}
        style={visible.length ? { height } : undefined}
        onKeyDown={onKeyDown}
      >
        {visible.map((it, i) => (
          <div
            key={it.value}
            id={optionId(i)}
            role="option"
            aria-selected={checked.has(it.value)}
            aria-disabled={it.disabled || undefined}
            data-active={(i === activeIndex) || undefined}
            className={cn('group/option', s.option())}
            onClick={() => {
              setActiveValue(it.value);
              toggle(it.value);
            }}
            onDoubleClick={() => !it.disabled && onTransfer([it.value])}
          >
            <span aria-hidden className={s.check()}>
              {checked.has(it.value) && <Check size={11} strokeWidth={3} />}
            </span>
            <span className={s.optionText()}>
              <span className={s.optionLabel()}>{it.label}</span>
              {it.description && <span className={s.optionDescription()}>{it.description}</span>}
            </span>
          </div>
        ))}
      </div>
      {visible.length === 0 && <div className={s.empty()} style={{ height }}>{items.length ? noMatchesText : emptyText}</div>}
      {footer && <div className={s.paneFoot()}>{footer}</div>}
    </section>
  );
}

export { TransferList, type TransferListProps, type TransferListLabels } from './TransferList';
export { TransferListPane, type TransferListPaneProps, type TransferListItem } from './TransferListPane';
export { transferListVariants, type TransferListVariantProps } from './transfer-list.variants';
export { doc as transferListDoc } from './TransferList.doc';

import { tv, type VariantProps } from '../../utils/tv';

